  'download.linux.source.desc': 'WhisPaste ist eine Flutter-App. Der Build aus dem Quellcode braucht Flutter und den Build-Schritt der Sprachengine aus BUILD.md.',
  'download.linux.build.intro': 'WhisPaste ist eine Flutter-App. Für den Build unter Linux braucht es Flutter und für On-Device-Whisper zusätzlich einen Build-Schritt der Sprachengine.',
  'download.linux.build.step1.title': 'Flutter installieren',
